package mage.player.ai;
import mage.Mana;import mage.abilities.*;import mage.cards.Card;import mage.constants.*;import mage.counters.CounterType;import mage.game.permanent.*;import java.util.*;
import static mage.player.ai.FourthSeatRealGameTest.check;import static mage.player.ai.RecoveryChecks.*;
public final class FourthSeatRecoveredBoundariesTest {
 static boolean hydra(FourthSeatRealGameTest.Fixture f)throws Exception{return (Boolean)Class.forName("mage.player.ai.FourthSeatCounterGrowthPolicy").getDeclaredMethod("hasOverwhelmingMultiplicativeThreat",UUID.class,mage.game.Game.class).invoke(null,f.bot.getId(),f.game);}
 public static void main(String[]args)throws Exception{
  for(String mode:new String[]{"normal","sick-tapped","small","archon","no-abilities","missing-blue","short-mana"})run("Typed Hydra future threat/resource boundary "+mode,()->{FourthSeatRealGameTest.Fixture f=FourthSeatRecoveredGrowthTest.army(0,false,false,!mode.equals("missing-blue"),mode.equals("short-mana")?2:8,5);Permanent p=f.board("m.MossbornHydra","Mossborn Hydra");p.addCounters(CounterType.P1P1.createInstance(mode.equals("small")?16:256),p.getAbilities().get(0),f.game);f.game.applyEffects();if(mode.equals("sick-tapped")){FourthSeatRecoveredGroupTest.sick(p);p.setTapped(true);}if(mode.equals("archon"))f.enemyBoard(0,"b.BlazingArchon","Blazing Archon");if(mode.equals("no-abilities")){f.game.addEffect(new mage.abilities.effects.common.continuous.LoseAllAbilitiesTargetEffect(Duration.EndOfTurn).setTargetPointer(new mage.target.targetpointer.FixedTarget(p,f.game)),p.getAbilities().get(0));f.game.applyEffects();}boolean threat=!mode.equals("small")&&!mode.equals("archon")&&!mode.equals("no-abilities");check(hydra(f)==threat,"Typed future-threat proof wrong");check(FourthSeatRecoveredGrowthTest.reserve(f)==(threat&&!mode.equals("missing-blue")&&!mode.equals("short-mana")),"Threat bypassed resource/color proof");if(mode.equals("sick-tapped"))check(p.isTapped()&&p.hasSummoningSickness(),"Future projection mutated actual permanent");});
  for(String boundary:new String[]{"normal","conditional","conditional-pool","triggered"})run("Large modal retained diversity/cache boundary "+boundary,()->{FourthSeatRealGameTest.Fixture f=fixture("l.LathrilBladeOfTheElves","Lathril, Blade of the Elves");Permanent own=f.board("l.LathrilBladeOfTheElves","Lathril, Blade of the Elves");for(int i=0;i<8;i++){f.board("g.GrizzlyBears","Grizzly Bears");f.enemyBoard(i%3,"s.SolRing","Sol Ring");f.enemyBoard(i%3,"g.GloriousAnthem","Glorious Anthem");}for(int i=0;i<335;i++)f.enemyBoard(i%3,"basiclands.Forest","Forest");f.board("n.NykthosShrineToNyx","Nykthos, Shrine to Nyx");for(int i=0;i<4;i++)f.board("basiclands.Forest","Forest");if(boundary.equals("conditional"))f.board("g.GiadaFontOfHope","Giada, Font of Hope");if(boundary.equals("triggered"))f.board("r.RegalBehemoth","Regal Behemoth");Card c=f.hand("c.CollectiveResistance","Collective Resistance");f.mana(c);if(boundary.equals("conditional-pool")){Permanent giada=f.board("g.GiadaFontOfHope","Giada, Font of Hope");ActivatedAbility mana=giada.getAbilities(f.game).getActivatedManaAbilities(Zone.BATTLEFIELD).get(0);check(f.bot.activateAbility(mana,f.game),"Actual conditional pool setup failed");giada.moveToZone(Zone.EXILED,null,f.game,false);}Card murder=f.enemyHand("m.Murder","Murder");murder.getSpellAbility().getTargets().get(0).addTarget(own.getId(),murder.getSpellAbility(),f.game);f.castEnemy(murder);cast(f,c,1);Map<?,?> admitted=(Map<?,?>)field(f.bot,"lastAdmittedModeSignatures");check(admitted.containsKey(c.getId())&&((Set<?>)admitted.get(c.getId())).size()==7,"Seven mode subsets lost before final admission");long hits=((Number)field(f.bot,"manaAvailabilityCacheHits")).longValue(),builds=((Number)field(f.bot,"manaAvailabilityBuildCount")).longValue();check(boundary.equals("normal")?hits>0:hits==0,"Cache crossed conditional/trigger boundary");System.out.println("RECOVERY_CACHE_METRICS boundary="+boundary+" builds="+builds+" hits="+hits);drain(f,20);check(f.game.getPermanent(own.getId())!=null,"Mixed modal choice failed threatened-own protection");if(boundary.equals("normal")){c.moveToZone(Zone.HAND,null,f.game,false);f.bot.getManaPool().init();for(Permanent p:f.game.getBattlefield().getAllActivePermanents(f.bot.getId()))if(p.isLand(f.game))p.setTapped(true);reject(f,c);check(((Number)field(f.bot,"manaAvailabilityCacheHits")).longValue()==0,"Prior callback funding cache leaked into empty-resource callback");}});
  run("Cache reservation keys are canonical and distinct",()->{FourthSeatRealGameTest.Fixture f=fixture("l.LathrilBladeOfTheElves","Lathril, Blade of the Elves");Card c=f.hand("c.CollectiveResistance","Collective Resistance");java.lang.reflect.Method m=ComputerPlayerFourthSeat.class.getDeclaredMethod("availabilityCacheKey",ActivatedAbility.class,Set.class);m.setAccessible(true);UUID a=UUID.randomUUID(),b=UUID.randomUUID();Set<UUID> first=new LinkedHashSet<>(Arrays.asList(a,b)),second=new LinkedHashSet<>(Arrays.asList(b,a));Object one=m.invoke(f.bot,c.getSpellAbility(),first),two=m.invoke(f.bot,c.getSpellAbility(),second),different=m.invoke(f.bot,c.getSpellAbility(),Collections.singleton(a));check(one.equals(two)&&!one.equals(different),"Cache reservation identity incorrect");});
  run("No-action fast pass avoids observation construction",()->{FourthSeatRealGameTest.Fixture f=fixture("a.AesiTyrantOfGyreStrait","Aesi, Tyrant of Gyre Strait");long before=((Number)field(f.bot,"observationBuildCount")).longValue();check(!f.bot.priority(f.game),"Unavailable empty-hand fixture acted");check(((Number)field(f.bot,"observationBuildCount")).longValue()==before,"No-action callback built full observation");});
  run("Held development cannot starve real payoff after fixed enumeration deadline",()->{FourthSeatRealGameTest.Fixture f=FourthSeatRecoveredGrowthTest.army(32,false,false,true,10,5);for(Permanent p:FourthSeatRecoveredGrowthTest.scutes(f))((PermanentCard)p).removeSummoningSickness();Card payoff=f.hand("m.MultaniYavimayasAvatar","Multani, Yavimaya's Avatar"),land=f.hand("basiclands.Forest","Forest");check(FourthSeatRecoveredGrowthTest.reserve(f),"Reserve proof missing");f.game.nextPlayableDelayMillis=100;cast(f,payoff,1);check(f.game.delayedPlayableCalculations==1,"Deterministic delay seam not exercised");Set<?> held=(Set<?>)field(f.bot,"lastHeldSources"),admitted=(Set<?>)field(f.bot,"lastAdmittedSources");check(held.contains(land.getId())&&!admitted.contains(land.getId())&&admitted.contains(payoff.getId()),"Held source consumed actionable admission budget");for(Card c:f.bot.getHand().getCards(f.game))if(c.getName().equals("Growth Spiral"))check(!admitted.contains(c.getId()),"Held Growth consumed admission budget");});
  run("Bounded modal helper preserves original and rejects opponent choice",()->{FourthSeatRealGameTest.Fixture f=fixture("l.LathrilBladeOfTheElves","Lathril, Blade of the Elves");f.board("g.GrizzlyBears","Grizzly Bears");f.enemyBoard(0,"s.SolRing","Sol Ring");f.enemyBoard(1,"g.GloriousAnthem","Glorious Anthem");Card c=f.hand("c.CollectiveResistance","Collective Resistance");Ability original=c.getSpellAbility();List<UUID> selected=new ArrayList<>(original.getModes().getSelectedModes());java.lang.reflect.Method generate=Class.forName("mage.player.ai.FourthSeatBoundedOptions").getDeclaredMethod("generate",Ability.class,mage.game.Game.class);generate.setAccessible(true);List<?> options=(List<?>)generate.invoke(null,original,f.game);check(options!=null&&!options.isEmpty()&&options.size()<=64,"Bounded helper absent/unbounded");check(original.getModes().getSelectedModes().equals(selected),"Helper mutated original mode selection");for(Mode m:original.getModes().values())for(mage.target.Target t:m.getTargets())check(t.getTargets().isEmpty(),"Helper mutated original targets");Ability opponent=original.copy();opponent.getModes().setChooseController(TargetController.OPPONENT);check(generate.invoke(null,opponent,f.game)==null,"Opponent-selected modes incorrectly generated by bot");});
  finish("RECOVERED_BOUNDARIES");
 }
}
